export const TAX_RATE = 0.1;

export function formatReceipt(receipt) {
  const tax = Math.round((receipt.amount * TAX_RATE) / (1 + TAX_RATE));
  return `Receipt ${receipt.id}: ${receipt.amount.toLocaleString('en-US')} yen (tax ${tax.toLocaleString('en-US')} yen included)`;
}
