// Issue #43: the pay button can be pressed twice before the first charge has finished.
test('a second call while the first is still running does not charge again (#43)', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const order = { id: 'o-3', total: 1500 };
  const [first, second] = await Promise.all([capture(order), capture(order)]);
  assert.equal(gateway.charges.length, 1);
  assert.equal(second, first);
  assert.equal(order.receipt, first);
});

test('two orders paid at the same time are each charged once', async () => {
  const gateway = createSandboxGateway();
  const capture = createCapture(gateway);
  const a = { id: 'o-4', total: 300 };
  const b = { id: 'o-5', total: 400 };
  const [ra, rb] = await Promise.all([capture(a), capture(b)]);
  assert.equal(gateway.charges.length, 2);
  assert.equal(ra.orderId, 'o-4');
  assert.equal(rb.orderId, 'o-5');
});

test('an order whose charge failed can be paid again', async () => {
  const sandbox = createSandboxGateway();
  let failNext = true;
  const gateway = {
    charges: sandbox.charges,
    async charge(orderId, amount) {
      if (failNext) {
        failNext = false;
        throw new Error('gateway down');
      }
      return sandbox.charge(orderId, amount);
    },
  };
  const capture = createCapture(gateway);
  const order = { id: 'o-6', total: 900 };
  const results = await Promise.allSettled([capture(order), capture(order)]);
  assert.deepEqual(results.map((r) => r.status), ['rejected', 'rejected']);
  assert.notEqual(order.paid, true);
  const receipt = await capture(order);
  assert.equal(receipt.amount, 900);
  assert.equal(gateway.charges.length, 1);
});
EOF
