// The pay button of the checkout page, without the DOM: click() takes the payment and shows the result.
// While a payment is running the button is disabled, and a click gets the running payment's result.
export function createPayButton({ capture, order, show }) {
  let pending = null;

  async function pay() {
    const receipt = await capture(order);
    show(`Paid: ${receipt.id}`);
    return receipt;
  }

  return {
    label: 'Pay',
    get disabled() {
      return pending !== null;
    },
    click() {
      if (pending) return pending;
      pending = pay().finally(() => {
        pending = null;
      });
      return pending;
    },
  };
}
EOF
