import { test } from 'node:test';
import assert from 'node:assert/strict';
import { createPayButton } from '../../src/ui/pay-button.js';
import { createCapture } from '../../src/checkout/capture.js';
import { createSandboxGateway } from '../../src/gateway.js';

test('a click takes the payment and shows the receipt number', async () => {
  const shown = [];
  const button = createPayButton({
    capture: async (order) => ({ id: 'ch_1', orderId: order.id, amount: order.total }),
    order: { id: 'o-1', total: 1200 },
    show: (text) => shown.push(text),
  });
  await button.click();
  assert.deepEqual(shown, ['Paid: ch_1']);
});

// Issue #43: the real capture and gateway behind the button, clicked twice before the first result.
test('two quick clicks charge the order once and give the same receipt (#43)', async () => {
  const gateway = createSandboxGateway();
  const shown = [];
  const order = { id: 'o-2', total: 2400 };
  const button = createPayButton({ capture: createCapture(gateway), order, show: (text) => shown.push(text) });
  const [first, second] = await Promise.all([button.click(), button.click()]);
  assert.equal(gateway.charges.length, 1);
  assert.equal(second, first);
  assert.deepEqual(shown, ['Paid: ch_1']);
});

test('the button cannot be pressed while the payment is running', async () => {
  let calls = 0;
  let finish;
  const button = createPayButton({
    capture: (order) => {
      calls += 1;
      return new Promise((resolve) => {
        finish = () => resolve({ id: 'ch_1', orderId: order.id, amount: order.total });
      });
    },
    order: { id: 'o-3', total: 500 },
    show: () => {},
  });
  assert.equal(button.disabled, false);
  const first = button.click();
  assert.equal(button.disabled, true);
  const second = button.click();
  assert.equal(calls, 1);
  finish();
  assert.equal(await second, await first);
  assert.equal(button.disabled, false);
});

test('the button can be pressed again after a failed payment', async () => {
  let calls = 0;
  const button = createPayButton({
    capture: async (order) => {
      calls += 1;
      if (calls === 1) throw new Error('gateway down');
      return { id: 'ch_1', orderId: order.id, amount: order.total };
    },
    order: { id: 'o-4', total: 500 },
    show: () => {},
  });
  await assert.rejects(button.click(), /gateway down/);
  assert.equal(button.disabled, false);
  const receipt = await button.click();
  assert.equal(receipt.id, 'ch_1');
});
